(function(root){
const core=typeof module==='object'&&module.exports?require('./tradeoff-core.js'):root.TradeoffCore;
const names={money:'Money kept',time:'Time kept',energy:'Effort saved',now:'Feelings now',later:'Feelings later',connection:'Connection',meaning:'Meaning',security:'Security',health:'Health / sustainable stress',flexibility:'Flexibility / control',other:'Your additional factor',outcome:'Expected outcome value'};
function decisionScore(options){
 if(!options?.factors)throw Error('Enter the criteria to compare.');
 const parts=[];
 for(const [key,label] of Object.entries(names)){
  const f=options.factors[key]||{weight:0};
  if(!Number.isFinite(f.weight)||f.weight<0||f.weight>5)throw Error(label+': choose importance from 0 to 5.');
  if(!f.weight)continue;
  if(!Number.isFinite(f.a)||!Number.isFinite(f.b))throw Error(label+': rate both options, or set importance to 0.');
  const resource=['money','time','energy'].includes(key);
  if(resource&&(f.a<0||f.b<0))throw Error(label+': costs cannot be negative.');
  if(key==='energy'&&(f.a<1||f.a>5||f.b<1||f.b>5))throw Error('Effort ratings must be from 1 to 5.');
  if(!resource&&(f.a<0||f.a>10||f.b<0||f.b>10))throw Error(label+': rate both options from 0 to 10.');
  const swing=resource?f.swing:10;
  if(!Number.isFinite(swing)||swing<=0)throw Error(label+': enter a positive major-change amount.');
  parts.push({key,label,weight:f.weight,delta:(resource?f.b-f.a:f.a-f.b)/swing});
 }
 const result=core.weightedTradeoff(parts,options.temporal),violations=[],alternativeViolations=[];
 for(const [key,label] of [['money','spending'],['time','time'],['energy','effort']]){
  const limit=options.limits?.[key];if(limit===null||limit===undefined)continue;
  if(!Number.isFinite(limit)||limit<0)throw Error('Enter valid nonnegative hard limits.');
  const f=options.factors[key];if(!f||!Number.isFinite(f.a)||!Number.isFinite(f.b)||f.a<0||f.b<0)throw Error('Both resource costs are needed to check '+label+' limits.');
  if(f.a>limit)violations.push(label);if(f.b>limit)alternativeViolations.push(label);
 }
 return {...result,violations,alternativeViolations,boundary:!!options.declined,verdict:core.constrainedVerdict(result,{preferred:violations,alternative:alternativeViolations,boundary:!!options.declined})};
}
if(typeof module==='object'&&module.exports)module.exports={decisionScore};if(!root.document)return;
const get=id=>document.getElementById(id),read=id=>get(id).value.trim()===''?NaN:Number(get(id).value),sign=n=>(n>0?'+':'')+n.toFixed(1);
function secondaryDetails(box,panel){if(Array.from(box.children).some(n=>n.dataset.secondary==='true'))return;const details=document.createElement('details');details.dataset.secondary='true';const summary=document.createElement('summary');summary.textContent='See individual forecasts and the full input table';details.append(summary);for(const node of Array.from(box.childNodes))if(node!==panel)details.append(node);box.append(details);}
function show(){if(!current)return;const old=get('decisionScoreResult');if(old)old.remove();const panel=document.createElement('section');panel.id='decisionScoreResult';panel.className='personal-result';get('numberDashboard').prepend(panel);const line=(tag,text)=>{const p=document.createElement(tag);p.textContent=text;panel.append(p)};const pairs={outcome:[read('decisionA_outcome'),read('decisionB_outcome')],money:[read('money'),read('altMoney')],time:[read('minutes')+read('recovery'),read('altMinutes')+read('altRecovery')],energy:[read('energy'),read('altEffort')],now:[read('scoreDoNow'),read('scoreAltNow')],later:[read('scoreDoLater'),read('scoreAltLater')],connection:[read('fitDo_connection'),read('fitAlt_connection')],meaning:[read('fitDo_meaning'),read('fitAlt_meaning')],security:[read('fitDo_security'),read('fitAlt_security')],health:[read('decisionA_health'),read('decisionB_health')],flexibility:[read('decisionA_flexibility'),read('decisionB_flexibility')],other:[read('decisionA_other'),read('decisionB_other')]};
// Existing optional monetary and recovery inputs mean zero when left blank, consistent with their cost table.
for(const [key,ids] of [['money',['money','altMoney']],['time',['minutes','recovery','altMinutes','altRecovery']]]){const val=id=>get(id).value===''?0:read(id);pairs[key]=key==='money'?ids.map(val):[val(ids[0])+val(ids[1]),val(ids[2])+val(ids[3])];}
let input={factors:{},limits:{},declined:get('decisionType').value==='relationship'&&get('interest').value==='declined'};for(const key of Object.keys(names)){input.factors[key]={weight:read('decisionWeight_'+key),a:pairs[key][0],b:pairs[key][1],swing:['money','time','energy'].includes(key)?read('decisionSwing_'+key):10};}for(const [key,id] of [['money','decisionMaxMoney'],['time','decisionMaxTime'],['energy','decisionMaxEffort']])input.limits[key]=get(id).value===''?null:read(id);
if(get('decisionType').value==='relationship'&&get('comfortableSpend').value!==''){const comfort=read('comfortableSpend');input.limits.money=input.limits.money===null?comfort:Math.min(input.limits.money,comfort);}
try{input.temporal=root.WamTimeEffects?.read('decision');const original=decisionScore(input),learning=root.WamDecisionLearning?.processDecision(input);if(learning)input=learning.input;const r=decisionScore(input);if(learning){current.decisionLearning={...learning.snapshot,originalScore:original.score,adjustedScore:r.score};}else delete current.decisionLearning;line('h3',`${r.score.toFixed(1)}/100 · ${r.verdict}`);if(r.temporal)line('p',root.WamTimeEffects.describe(r.temporal));line('p',`Main option: ${get('task').value}. Alternative: ${get('alt').value}. Higher scores favor the main option. This is a preference score for this pair, not a happiness forecast or probability. Scores from decisions using different criteria or priorities are not directly comparable.`);if(r.boundary)line('p','Their refusal or request for space overrides every score. Do not pursue this option.');if(r.violations.length)line('p','Main option exceeds your '+r.violations.join(', ')+' limit.');if(r.alternativeViolations.length)line('p','Alternative exceeds your '+r.alternativeViolations.join(', ')+' limit.');if(r.violations.length||r.alternativeViolations.length)line('p','Hard limits override the preference score. Revise any option that exceeds them.');if(get('decisionType').value==='relationship'&&get('comfortableSpend').value!=='')line('p','Your relationship spending comfort amount is included as a spending limit.');if(learning){line('p',learning.summary);if(learning.snapshot.applied)line('p',`Before learning: ${original.score.toFixed(1)}/100. With learned estimates: ${r.score.toFixed(1)}/100. Your importance weights, money inputs and hard limits are unchanged.`);for(const change of learning.snapshot.changes.filter(c=>c.applied))line('p',`${change.label}: your forecast ${change.original.toFixed(1)} → learned estimate ${change.value.toFixed(1)} ${change.unit||'/10'} · ${change.n} comparable outcomes; ${change.checked} chronological checks; error ${change.mae.toFixed(2)} vs ${change.originalMae.toFixed(2)} before correction.`);}if(learning?.snapshot.changes.some(c=>c.kind==='resource'&&c.applied))line('p',`Resources used in this score: main option ${input.factors.time.a.toFixed(1)} total minutes and effort ${input.factors.energy.a.toFixed(1)}/5; alternative ${input.factors.time.b.toFixed(1)} total minutes and effort ${input.factors.energy.b.toFixed(1)}/5. Time includes recovery.`);for(const f of r.parts)line('p',`${f.label}: ${sign(f.points)} score points · importance ${f.weight}/5${f.capped?' · major-change cap reached':''}.`);line('p',`Assumption check: ${r.low.toFixed(1)}–${r.high.toFixed(1)}/100 if all included comparisons shift by ±0.1 normalized units. This is a sensitivity scenario, not a confidence interval.`);line('p','Calculation: 50 + 50 × weighted mean of capped factor changes. Resource change = (alternative cost − main cost) / your major-change amount. Benefit change = (main rating − alternative rating) / 10. Each factor is capped at −1 to +1.');current.decisionTradeoff={inputs:input,result:r};if(learning)current.profileSummary+='\n\nPERSONAL OUTCOME CALIBRATION\n'+learning.summary+'\nOriginal tradeoff score: '+original.score.toFixed(1)+'; adjusted: '+r.score.toFixed(1);current.profileSummary+='\n\nCOMBINED PERSONAL DECISION SCORE\n'+panel.textContent;}catch(e){line('h3','Personalized score needs your input');line('p',e.message);delete current.decisionTradeoff;get('save').disabled=true;}secondaryDetails(get('numberDashboard'),panel);}
get('form').addEventListener('submit',show);
const before=renderNumbers;renderNumbers=function(){before();show()};
for(const id of ['example','purchaseExample','relationshipExample'])get(id).addEventListener('click',()=>{for(const key of Object.keys(names))get('decisionWeight_'+key).value=0;for(const [key,w,swing] of [['money',2,50],['time',3,60],['energy',3,2],['now',3],['later',4]]){get('decisionWeight_'+key).value=w;if(swing)get('decisionSwing_'+key).value=swing;}get('decisionMaxMoney').value='';get('decisionMaxTime').value='';get('decisionMaxEffort').value='';show()});
get('decisionScoreSettings').addEventListener('input',()=>{if(current&&get('form').checkValidity()){addPerspective();renderNumbers()}});
})(typeof globalThis!=='undefined'?globalThis:this);
